  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { __schema { queryType { fields { name } } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { searchDocuments(query: \"Retention Playbook\") { nodes { id name title description team { name key } } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { __type(name: \"DocumentSearchResult\") { fields { name type { name kind ofType { name } } } } }"
